// Valid category options straight from Zendesk (source of truth, the Sheets directory can be outdated)
const opts = $('Get Category Options').first().json.ticket_field?.custom_field_options || [];
const tags = opts.map(o => o.value);
// Catalog for the agent prompt: "Name → tag" (internal categories left out, they are never customer tickets)
const catalog = opts.filter(o => !/^Internal::/i.test(o.name)).map(o => o.name + ' → ' + o.value).join('\n');
return [{ json: { tags, catalog } }];

// Runs ONCE per execution, after all tickets of this run were routed and logged.
// Stateless pattern detector (no workflow static data): reads the 'Ruteo Nova' log, counts tickets
// flagged possible_product_issue per category in the last 3h, and alerts only when THIS run makes a
// category cross the threshold (so the same cluster is not alerted every 5 minutes).
const WINDOW_MS = 3 * 60 * 60 * 1000, THRESHOLD = 3;
const SLACK = { Justin: 'U0CA6JRHVM3', Sudu: 'U03U61FQJKA', Jaime: 'U0CEQGZN7AB', Caro: 'U063KEHP2SD', Cristian: 'U0AU0TPJDM5', Brisa: 'U0AJMGBVCR5', Miguel: 'U06LW3ASH7D', Samuel: 'U099JCSKB3Q', Mike: 'U09NCCJJ2UT' };
let thisRun = new Set();
try { thisRun = new Set($('Filter & Prioritize').all().map(i => String(i.json.ticket_id))); } catch (e) {}
const now = Date.now();
const toMs = ts => { const d = new Date(String(ts).replace(' ', 'T') + ':00-05:00'); return isNaN(d) ? 0 : d.getTime(); };
const rows = $input.all().map(i => i.json)
  .filter(r => String(r.possible_product_issue).toLowerCase() === 'true' && now - toMs(r.timestamp) < WINDOW_MS);
const byCat = {};
for (const r of rows) {
  const k = r.category_tag || r.category || 'unknown';
  (byCat[k] = byCat[k] || new Map()).set(String(r.ticket_id), r);
}
const out = [];
for (const [k, m] of Object.entries(byCat)) {
  const all = [...m.values()];
  const before = all.filter(r => !thisRun.has(String(r.ticket_id)));
  if (all.length >= THRESHOLD && before.length < THRESHOLD) {
    const owners = [...new Set(all.map(r => r.owner).filter(Boolean))];
    const last = all[all.length - 1];
    out.push({ json: {
      cluster_category: last.category || k,
      cluster_count: all.length,
      cluster_tickets: all.map(r => '<https://getontop.zendesk.com/agent/tickets/' + r.ticket_id + '|#' + r.ticket_id + '> (' + r.owner + ')').join(', '),
      cluster_signatures: [...new Set(all.map(r => r.issue_signature).filter(Boolean))].join(' · '),
      cluster_owner_mentions: owners.map(o => SLACK[o] ? '<@' + SLACK[o] + '>' : o).join(' '),
      owner_slack_id: SLACK[last.owner] || '',
    }});
  }
}
return out;

